#include <string>
#include <algorithm>

class Solution {
public:
    int maxDistance(std::string s, int k) {
        auto check = [&](char dir1, char dir2) -> int {
            int ans = 0;
            int pos = 0;
            int opp = 0;
            for (char ch : s) {
                if (ch == dir1 || ch == dir2) {
                    pos++;
                } else {
                    pos--;
                    opp++;
                }
                int dist = pos + 2 * std::min(k, opp);
                ans = std::max(ans, dist);
            }
            return ans;
        };

        return std::max({
            check('N', 'E'),
            check('N', 'W'),
            check('S', 'E'),
            check('S', 'W')
        });
    }
};

class Solution {
    public int maxDistance(String s, int k) {
        return Math.max(
            Math.max(check(s, k, 'N', 'E'), check(s, k, 'N', 'W')),
            Math.max(check(s, k, 'S', 'E'), check(s, k, 'S', 'W'))
        );
    }

    private int check(String s, int k, char dir1, char dir2) {
        int ans = 0;
        int pos = 0;
        int opp = 0;
        for (char ch : s.toCharArray()) {
            if (ch == dir1 || ch == dir2) {
                pos++;
            } else {
                pos--;
                opp++;
            }
            int dist = pos + 2 * Math.min(k, opp);
            ans = Math.max(ans, dist);
        }
        return ans;
    }
}

var maxDistance = function(s, k) {
    function check(dir1, dir2) {
        let ans = 0;
        let pos = 0;
        let opp = 0;
        for (let i = 0; i < s.length; i++) {
            const ch = s[i];
            if (ch === dir1 || ch === dir2) {
                pos++;
            } else {
                pos--;
                opp++;
            }
            const dist = pos + 2 * Math.min(k, opp);
            if (dist > ans) ans = dist;
        }
        return ans;
    }

    return Math.max(
        check('N', 'E'),
        check('N', 'W'),
        check('S', 'E'),
        check('S', 'W')
    );
};
